# organize_data.py
import os
import shutil
import glob
from pathlib import Path

downloads_dir = str(Path.home() / "Downloads")
data_dir = "data"
os.makedirs(data_dir, exist_ok=True)

# Find all .npy files generated by recorder.html
pattern = os.path.join(downloads_dir, "*_signer_*.npy")
files = glob.glob(pattern)

print(f"Found {len(files)} recorded clips in Downloads.")

count = 0
for filepath in files:
    filename = os.path.basename(filepath)
    parts = filename.split("_signer_")
    if len(parts) == 2:
        sign_name = parts[0]
        sign_folder = os.path.join(data_dir, sign_name)
        os.makedirs(sign_folder, exist_ok=True)
        dest_path = os.path.join(sign_folder, filename)
        
        try:
            # Copy instead of move so Windows doesn't block the file
            shutil.copy2(filepath, dest_path)
            count += 1
        except Exception as e:
            print(f"Skipped {filename}: {e}")

print(f"✅ Successfully copied {count} clips into the 'data/' directory!")